interface Printable{void print();}interface Scannable{void scan();}class MultiFunctionPrinter implements Printable,Scannable{public void print(){System.out.println("Multifunction printer printing");}public void scan(){System.out.println("Multifunction printer scanning");}}class BasicPrinter implements Printable{public void print(){System.out.println("Basic printer printing");}}public class Q4_Multiple_Inheritance_Using_Interfaces{public static void main(String[]x){Printable p=new BasicPrinter();p.print();MultiFunctionPrinter m=new MultiFunctionPrinter();m.print();m.scan();}}
